#![allow(dead_code)]
#[path="../mixins/sunset/bot_tactics_policy.rs"]mod policy;
use policy::*;
fn candidate(id:u32,distance:f64)->Candidate{Candidate{id,distance,life:20.,totem:true,low_armor:false,retaliate:false}}
fn view(tick:u64)->FightView{FightView{tick,health:20.,absorption:0.,totems:4,offhand_totem:true,enemies:1,risk:0.,target_life:20.,target_totem:true,distance:3.,hole:false,target_y:0.,eat_below:14.}}
#[test]fn target_close_challenger_requires_twenty_continuous_ticks(){let mut c=TargetChoice::default();assert_eq!(c.choose(0,16.,false,&[candidate(1,6.)]),Some(1));let new=Candidate{id:2,distance:3.,life:1.,totem:false,low_armor:true,retaliate:true};for t in 1..21{assert_eq!(c.choose(t,16.,false,&[candidate(1,6.),new]),Some(1));}assert_eq!(c.choose(21,16.,false,&[candidate(1,6.),new]),Some(2));}
#[test]fn target_far_challenger_requires_six_ticks_and_lost_challenger_resets(){let mut c=TargetChoice::default();c.choose(0,16.,false,&[candidate(1,10.)]);for t in 1..7{assert_eq!(c.choose(t,16.,false,&[candidate(1,10.),candidate(2,3.)]),Some(1));}assert_eq!(c.choose(7,16.,false,&[candidate(1,10.),candidate(2,3.)]),Some(2));}
#[test]fn regroup_retains_known_rival_to_sixty_four_but_does_not_acquire_outside_range(){let mut c=TargetChoice::default();c.choose(1,16.,false,&[candidate(1,5.)]);assert_eq!(c.choose(2,16.,true,&[candidate(1,60.)]),Some(1));assert_eq!(c.choose(3,16.,false,&[candidate(1,60.)]),None);assert_eq!(c.choose(4,16.,true,&[candidate(1,60.)]),None);}
#[test]fn target_nan_is_never_selected(){let mut c=TargetChoice::default();assert_eq!(c.choose(1,16.,false,&[candidate(1,f64::NAN)]),None);assert!(worth(Candidate{life:f64::INFINITY,..candidate(1,3.)}).is_none());}
#[test]fn stance_caps_keep_health_reserve_even_when_totem_equipped(){let s=Stance::Press.steer(4,5.,true,false,false,120);assert_eq!(s.self_cap,4.);assert_eq!(s.min,3.5);assert_eq!(s.floor,121);assert_eq!(Stance::Guard.steer(4,5.,false,false,false,120).self_cap,1.);assert_eq!(Stance::Press.steer(4,20.,true,true,false,120).min,2.);}
#[test]fn own_three_observed_pops_enter_run_for_two_hundred_ticks(){let mut f=Fight::default();f.own_pop(1);f.own_pop(10);f.own_pop(20);assert_eq!(f.stance(view(219),&Rival::default()),Stance::Run);assert_eq!(f.stance(view(220),&Rival::default()),Stance::Press);}
#[test]fn pop_history_survives_target_switch_and_old_streak_expires(){let mut f=Fight::default();f.own_pop(1);f.own_pop(2);f.start(5,3);f.own_pop(4);assert_eq!(f.run_until,204);let mut f=Fight::default();f.own_pop(1);f.own_pop(700);f.own_pop(701);assert_eq!(f.run_until,0);}
#[test]fn food_hysteresis_starts_two_below_and_absorption_clears(){let mut f=Fight::default();let mut v=view(1);v.health=13.;f.stance(v,&Rival::default());assert!(!f.needs_food);v.health=12.;f.stance(v,&Rival::default());assert!(f.needs_food);v.health=18.;f.stance(v,&Rival::default());assert!(f.needs_food);v.absorption=4.;f.stance(v,&Rival::default());assert!(!f.needs_food);}
#[test]fn no_totem_two_near_enemies_extend_run_window(){let mut f=Fight::default();let mut v=view(100);v.totems=0;v.enemies=2;assert_eq!(f.stance(v,&Rival::default()),Stance::Run);assert_eq!(f.run_until,140);}
#[test]fn target_retotem_learning_requires_observed_hand_return_or_timeout(){let mut f=Fight::default();let mut r=Rival::default();f.their_pop=Some(10);let mut v=view(15);v.target_totem=false;f.observe(v,&mut r);assert_eq!(r.retotems,0);v.target_totem=true;v.tick=17;f.observe(v,&mut r);assert_eq!(r.retotem,7.);assert!(f.their_pop.is_none());}
#[test]fn hole_and_low_spell_learning_are_observation_bounded(){let mut f=Fight::default();let mut r=Rival::default();let mut v=view(1);v.hole=true;v.target_life=6.;f.observe(v,&mut r);f.low_since=Some((1,true));v.tick=900;v.hole=false;v.target_life=15.;f.observe(v,&mut r);assert_eq!(r.hole_ticks,600.);assert_eq!(r.pearl_rate,1.);}
#[test]fn launch_is_learned_only_after_eight_ticks_and_actual_height(){let mut f=Fight::default();let mut r=Rival::default();f.struck(10,1.);let mut v=view(17);v.target_y=1.4;f.observe(v,&mut r);assert_eq!(r.launches,0);v.tick=18;v.target_y=1.1;f.observe(v,&mut r);assert_eq!(r.launches,1);assert_eq!(r.launch_rate,1.);assert_eq!(f.next_launch,90);}
#[test]fn adaptive_opener_explores_each_distance_bucket_then_fades_only_that_bucket(){let mut r=Rival::default();assert_eq!(r.opener(2.5,0.),0);r.opened(0,2.5,1.);assert_eq!(r.opener(2.5,0.),1);r.opened(1,3.5,0.);assert_eq!(r.tries[0],1.);r.opened(1,2.5,0.);assert!((r.tries[0]-0.97).abs()<1e-12);assert_eq!(r.tries[5],1.);}
#[test]fn rival_requires_enough_samples_before_behavior_switch(){let mut r=Rival::default();for _ in 0..3{r.launched(false);}assert!(!r.shrugs());r.launched(false);assert!(r.shrugs());r.left_hole(150);assert!(!r.camper());r.left_hole(150);assert!(r.camper());r.low_spell(true);assert!(!r.pearl_low());r.low_spell(true);assert!(r.pearl_low());}
#[test]fn correction_pause_ignores_far_teleport_and_recent_real_pearl(){let mut p=PauseClock::default();for i in 0..10{p.correction(i,100*i,7.,100);p.correction(i,100*i,1.,59);}assert_eq!(p.state(10),Pause::Go);p.correction(10,1000,1.,60);assert_eq!(p.state(19),Pause::Hold);assert_eq!(p.state(20),Pause::Go);}
#[test]fn six_small_corrections_within_ten_seconds_stop_but_older_do_not_count(){let mut p=PauseClock::default();p.correction(0,0,1.,100);for i in 1..6{p.correction(i,i*2500,1.,100);}assert_ne!(p.state(10),Pause::Stop);p.correction(10,12501,1.,100);assert_eq!(p.state(10),Pause::Hold);p.correction(11,12502,1.,100);assert_eq!(p.state(11),Pause::Stop);}
#[test]fn manual_yield_and_context_holds_have_exact_tick_boundaries(){let mut p=PauseClock::default();p.manual(5);assert_eq!(p.state(34),Pause::Yield);assert_eq!(p.state(35),Pause::Go);p.context(40,true);assert_eq!(p.state(79),Pause::Hold);assert_eq!(p.state(80),Pause::Go);}
#[test]fn native_time_samples_drive_slow_server_guard(){let mut p=PauseClock::default();p.time(0,0);p.time(20,2000);assert_eq!(p.tps,15.);assert!(!p.slow());p.time(40,4000);assert_eq!(p.tps,12.5);assert!(p.slow());}
#[test]fn body_flight_calls_collision_and_stops_at_actual_floor(){let mut calls=0;let stop=body_path([0.,1.,0.],[0.;3],[0.;3],false,0.546,40,|at,mut d|{calls+=1;if at[1]+d[1]<0.{d[1]=-at[1];}Some(d)}).unwrap();assert!(stop.landed);assert_eq!(stop.at[1],0.);assert!(calls<40);}
#[test]fn body_flight_cannot_turn_missing_collision_data_into_open_air(){assert!(body_path([0.;3],[0.;3],[0.;3],false,0.546,40,|_,_|None).is_none());assert!(body_path([f64::NAN,0.,0.],[0.;3],[0.;3],false,0.546,40,|_,d|Some(d)).is_none());}
#[test]fn native_lift_knockback_resistance_one_suppresses_speculative_kick(){let mut a=Air::default();a.target=Some(2);a.kicked(1,[3.,0.,0.],[0.;3],-90.,true,1.,0.546);assert!(a.kick.is_none());a.kicked(2,[3.,0.,0.],[0.;3],-90.,true,0.,0.546);let(_,_,v,_)=a.kick.unwrap();assert!((v[1]-0.4).abs()<1e-12);assert!((v[0]-0.7).abs()<1e-12);}
#[test]fn air_observed_acceleration_requires_two_inferences_and_bounds_motion(){let mut a=Air::default();let mut x=0.;let mut v=0.4;for tick in 0..4{a.note(2,tick,[x,1.,0.],false,false);v=v*0.91+0.02;x+=v;}let req=a.request(3,2,&Rival::default()).unwrap();assert!((req.2[0]-0.02).abs()<1e-10);assert!(a.request(3,0,&Rival::default()).is_none());a.note(2,4,[x,0.,0.],true,false);assert!(a.request(4,2,&Rival::default()).is_none());}
#[test]fn blast_spoils_unobserved_launch_and_resets_samples(){let mut a=Air::default();a.target=Some(2);a.kicked(1,[3.,0.,0.],[0.;3],-90.,true,0.,0.546);a.blast([3.,0.,0.]);assert!(a.kick.is_none());}
#[test]fn early_real_launch_samples_keep_prediction_available_before_two_acceleration_inferences(){let mut air=Air::default();air.target=Some(2);air.kicked(0,[1.,1.,0.],[0.,1.,0.],-90.,false,0.,0.546);let mut at=[1.,1.,0.];let(mut x,mut y)=(0.4,0.4);for i in 1..=3{if i>1{x*=if i==2{0.546}else{0.91};y=(y-0.08)*0.98;}x+=0.02;at[0]+=x;at[1]+=y;if i==1||i==3{air.note(2,i,at,false,false);}}let request=air.request(3,2,&Rival::default()).unwrap();assert!((request.2[0]-0.02).abs()<1e-10);}
#[test]fn pearl_integrator_has_bounded_one_hundred_steps_and_real_hit_endpoint(){let mut queries=0;let landing=pearl_path([0.,1.,0.],[1.,0.,0.],|a,b|{queries+=1;if a==b{Some((None,false))}else if b[0]>=2.{Some((Some([2.,b[1],0.]),false))}else{Some((None,false))}}).unwrap();assert_eq!(landing.ticks,3);assert_eq!(landing.at[0],2.);assert_eq!(queries,6);let mut queries=0;assert!(pearl_path([0.;3],[0.;3],|_,_|{queries+=1;Some((None,false))}).is_none());assert_eq!(queries,200);}
#[test]fn pearl_vertical_inheritance_is_only_airborne(){assert_eq!(pearl_velocity(0.,0.,[0.2,0.7,0.3],true),[0.2,0.,1.8]);assert_eq!(pearl_velocity(0.,0.,[0.2,0.7,0.3],false),[0.2,0.7,1.8]);}
#[test]fn block_attempts_require_payload_and_world_agreement_and_survive_unrelated_ticks(){let mut b=Blocks::default();assert!(b.sent([1,2,3],0,10,Purpose::Surround));assert!(!b.acknowledged([1,2,3],1));b.payload([1,2,3],1);assert!(!b.acknowledged([1,2,3],0));assert!(b.acknowledged([1,2,3],1));assert!(!b.can_send([1,2,3],1,100));assert!(b.can_send([1,2,3],0,100));}
#[test]fn failed_block_retries_stop_after_three_and_sixty_four_cells_fail_closed(){let mut b=Blocks::default();for t in [0,20,40]{assert!(b.sent([0;3],0,t,Purpose::Surround));}assert!(!b.can_send([0;3],0,60));for n in 1..64{assert!(b.sent([n,0,0],0,0,Purpose::Surround));}assert!(!b.can_send([64,0,0],0,100));}
#[test]fn camp_real_spawn_id_and_matching_remove_are_required_to_rearm(){let mut c=CampLedger::default();for t in [0,20,40]{assert!(c.sent([0;3],t));}assert!(!c.can_send([0;3],60));c.spawned([1,0,0],99,41);assert!(!c.can_send([0;3],60));c.spawned([0;3],99,41);assert!(!c.can_send([0;3],60));c.removed(&[98]);assert!(!c.can_send([0;3],60));c.removed(&[99]);assert!(c.can_send([0;3],60));}
#[test]fn stand_cover_changes_guard_preference_without_ignoring_travel_cost(){let own=[0.,0.,0.];let enemy=[3.2,0.,0.];let open=stand_score(own,own,enemy,0.,Stance::Guard).unwrap();let sheltered=stand_score([0.,0.,1.],own,enemy,1.,Stance::Guard).unwrap();assert!(sheltered>open+0.5);assert!(stand_score([f64::NAN,0.,0.],own,enemy,1.,Stance::Guard).is_none());}

fn critical()->CriticalFoodView{CriticalFoodView{life:4.,distance:7.99,needs_food:true,eating:false,using_food:false,gapple_hotbar:true,offhand_totem:false}}
#[test]fn critical_food_retreat_uses_exact_life_distance_material_and_totem_boundary(){let v=critical();assert!(critical_food_retreat(v));assert!(!critical_food_retreat(CriticalFoodView{life:4.001,..v}));assert!(!critical_food_retreat(CriticalFoodView{distance:8.,..v}));assert!(!critical_food_retreat(CriticalFoodView{gapple_hotbar:false,..v}));assert!(!critical_food_retreat(CriticalFoodView{offhand_totem:true,..v}));assert!(!critical_food_retreat(CriticalFoodView{life:f64::NAN,..v}));}
#[test]fn critical_active_food_use_retreat_does_not_invent_food_intent(){let v=CriticalFoodView{needs_food:false,..critical()};assert!(!critical_food_retreat(v));assert!(!critical_food_retreat(CriticalFoodView{eating:true,..v}));assert!(critical_food_retreat(CriticalFoodView{eating:true,using_food:true,..v}));}
#[test]fn critical_no_totem_retreat_never_becomes_a_suicidal_pearl_throw(){let v=critical();assert!(critical_food_retreat(v));assert!(!pearl_health_ready(v.life,v.offhand_totem));assert!(!pearl_health_ready(6.,false));assert!(pearl_health_ready(6.001,false));assert!(pearl_health_ready(4.,true));assert!(!pearl_health_ready(f64::INFINITY,true));}
